files.content:
.field{
  display:flex;
  flex-direction:column;
  gap:var(--s-1);
}
.label{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
  color:var(--obsidian-300);
}
.input, .textarea{
  background:var(--surface-field);
  border:var(--bw-1) solid var(--border-input);
  border-radius:var(--r-md);
  color:var(--obsidian-100);
  min-height:var(--s-10);
  padding:var(--s-2) var(--s-3);
  font-family:var(--font-sans);
  font-size:var(--t-small);
  outline:none;
  transition:all var(--d-quick) var(--ease-standard);
  width:100%;
}
.input:hover:not(:focus):not(:disabled):not([readonly]):not([aria-invalid="true"]), .textarea:hover:not(:focus):not(:disabled):not([readonly]):not([aria-invalid="true"]){
  border-color:var(--obsidian-300);
}
.input:focus, .textarea:focus{
  border-color:var(--primary-500);
  box-shadow:var(--ring-field);
}
.input[aria-invalid="true"], .textarea[aria-invalid="true"]{
  border-color:var(--danger);
}
.input[aria-invalid="true"]:focus, .textarea[aria-invalid="true"]:focus{
  border-color:var(--danger);
  box-shadow:var(--ring-field-danger);
}
.input:disabled, .textarea:disabled{
  opacity:var(--opacity-disabled);
  cursor:not-allowed;
}
.input[readonly], .textarea[readonly]{
  background:var(--obsidian-900);
  color:var(--obsidian-300);
}
.input::placeholder, .textarea::placeholder{
  color:var(--obsidian-300);
}
.input-wrap{
  position:relative;
  width:100%;
}
.input-wrap:has(> .input-action) .input{
  padding-right:var(--s-10);
}
.input[type="search"]::-webkit-search-cancel-button, .input[type="search"]::-webkit-search-decoration{
  -webkit-appearance:none;
  appearance:none;
}
.help{
  font-size:var(--t-caption);
  color:var(--obsidian-300);
}
.input-action{
  position:absolute;
  right:var(--s-1);
  top:50%;
  transform:translateY(-50%);
  display:grid;
  place-items:center;
  width:var(--s-8);
  height:var(--s-8);
  border:0;
  background:transparent;
  cursor:pointer;
  color:var(--obsidian-300);
  border-radius:var(--r-sm);
  transition:color var(--d-quick) var(--ease-standard), background var(--d-quick) var(--ease-standard);
}
.input-action:hover{
  color:var(--obsidian-100);
  background:var(--obsidian-800);
}
.input-action:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--s-px);
  box-shadow:var(--ring-halo);
  color:var(--obsidian-100);
}
.input:placeholder-shown ~ .input-action[data-input-clear], .input[readonly] ~ .input-action[data-input-clear], .input:disabled ~ .input-action{
  visibility:hidden;
}
@media (prefers-reduced-motion: reduce){
  .input-action{
    transition:none;
  }
}
